window.AtlasUI={
 icon(name){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ATLAS_ICONS[name]||ATLAS_ICONS['layers']}</svg>`},
 avatar(c){const initials=String(c.author||'?').replace('@','').slice(0,1).toUpperCase().replace(/[<>&"']/g,'');return c.author==='Shuryne'?'<span class="avatar avatar-photo"><img src="https://avatars.githubusercontent.com/u/24755095?v=4" alt="Shuryne 的 GitHub 头像" width="36" height="36" loading="lazy" decoding="async"></span>':c.author==='ailingqu'?'<span class="avatar avatar-photo"><img src="https://avatars.githubusercontent.com/u/46532197?v=4" alt="ailingqu 的 GitHub 头像" width="36" height="36" loading="lazy" decoding="async"></span>':`<span class="avatar" aria-label="作者 ${initials}">${initials}</span>`},
 navIcon(v){return ({'ChatGPT Images 2.6':'sparkles','多模型工作流':'workflow','多模型对比':'git-compare-arrows','表情包与贴纸':'smile','快闪与品牌动效':'clapperboard','氛围循环动画':'moon','像素风与界面动效':'monitor','动图与动画':'film','游戏美术':'gamepad-2','海报设计':'palette','模型对比':'git-compare-arrows','视频工作流':'workflow','地图设计':'map','像素动画':'grid-2x2','摄影对比':'camera'})[v]||'layers'},
 syncFilters(){document.querySelectorAll('[data-model]').forEach(b=>{const on=b.dataset.model===document.querySelector('#model').value;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on))});document.querySelectorAll('[data-category]').forEach(b=>{const on=b.dataset.category===document.querySelector('#category').value;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on))})}
};
